/* ─── Buttons: solid (one per view), line (the rest), danger, ghost ─── */
.btn { min-height: var(--control-md); display: inline-flex; align-items: center; justify-content: center; gap: var(--s3); padding: 14px 24px; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; border-radius: var(--radius); transition: transform var(--base), background var(--fast), color var(--fast); }
.btn:active:not(:disabled) { transform: scale(0.98); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn-solid { background: var(--foreground); color: var(--background); }
.btn-solid:hover:not(:disabled) { background: var(--ink-2); }
.btn-line { box-shadow: inset 0 0 0 1px var(--foreground); }
.btn-line:hover:not(:disabled) { background: var(--foreground); color: var(--background); }
.btn-danger { box-shadow: inset 0 0 0 1px var(--danger); color: var(--danger); }
.btn-danger:hover:not(:disabled) { background: var(--danger); color: var(--background); }
.btn-ghost { min-height: 0; padding-inline-start: 0; padding-inline-end: 0; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--muted); }
.btn-ghost:hover:not(:disabled) { text-decoration-color: currentColor; }
.btn-sm { min-height: var(--control-sm); padding: 6px 12px; font-size: var(--text-xs); }
.btn-lg { min-height: var(--control-lg); padding: 14px 32px; font-size: var(--text-base); }
.btn-ghost.btn-sm, .btn-ghost.btn-lg { min-height: 0; }
.btn-block { width: 100%; }

/* ─── Marks ─── */
.swatch { width: 14px; height: 14px; flex: none; margin-top: 4px; display: inline-block; }
.check { width: 20px; height: 20px; flex: none; display: grid; place-items: center; font-size: var(--text-xs); font-weight: 500; margin-top: 2px; }
.check-pass { border: 1px solid var(--foreground); }
.check-fail { background: var(--accent); color: var(--on-accent); }
.badge { display: inline-flex; align-items: center; gap: var(--s1); padding: 2px 8px; font-size: var(--text-xs); font-weight: 500; border: 1px solid var(--rule); white-space: nowrap; }
.badge-solid { background: var(--foreground); color: var(--background); border-color: var(--foreground); }
.badge-accent { background: var(--accent); color: var(--on-accent); border-color: var(--accent); }
.kbd { display: inline-block; padding: 0 6px; font-size: var(--text-xs); border: 1px solid var(--rule); border-bottom-width: 2px; line-height: 18px; }
/* A line of keyboard hints under a field: each key with its word, groups --s3 apart. */
.key-hints { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s1) var(--s3); font-size: var(--text-xs); color: var(--muted); }
.key-hints > span { display: inline-flex; align-items: center; gap: var(--s1); }
.dot { width: 8px; height: 8px; border-radius: var(--round); background: var(--accent); display: inline-block; flex: none; }

/* Heat: five steps of the app's accent, for counts over time. */
.heat-0 { background: var(--wash-2); }
.heat-1 { background: color-mix(in srgb, var(--accent) 25%, var(--background)); }
.heat-2 { background: color-mix(in srgb, var(--accent) 50%, var(--background)); }
.heat-3 { background: color-mix(in srgb, var(--accent) 75%, var(--background)); }
.heat-4 { background: var(--accent); }

/* Icon button: a square .btn. */
.btn.btn-icon { height: auto; padding: var(--s3); aspect-ratio: 1; display: inline-grid; place-items: center; line-height: 0; }
.btn.btn-icon.btn-sm { height: auto; padding: var(--s2); }
.btn-icon svg { width: 1em; height: 1em; }

/* Popover, dropdown menu and select content on Radix: a bordered panel above the page. */
.popover { z-index: var(--z-drawer); min-width: 200px; max-width: min(360px, 92vw); padding: var(--s4); background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); animation: dialog-fade var(--fast) var(--ease); }
.popover:focus-visible { outline-offset: 2px; }
.menu-content { z-index: var(--z-drawer); min-width: 200px; padding: var(--s1) 0; background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); animation: dialog-fade var(--fast) var(--ease); }
.menu-content .menu-item { cursor: pointer; }
.menu-content .menu-item[data-highlighted] { background: var(--foreground); color: var(--background); outline: none; }
.menu-content .menu-item[data-disabled] { opacity: 0.5; pointer-events: none; }
.menu-content .menu-item[data-variant="danger"][data-highlighted] { background: var(--danger); }
.menu-label { padding: var(--s2) var(--s4); font-size: var(--text-xs); text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }
.menu-indicator { width: 14px; display: inline-flex; justify-content: center; }
.menu-item-check { display: flex; align-items: center; gap: var(--s3); }

/* Notification center: bell + badge, and a panel with a header, a list and an empty line. */
.notification-center { position: relative; display: inline-flex; }
.notification-center-badge { position: absolute; inset-block-start: calc(var(--s1) * -1); inset-inline-end: calc(var(--s1) * -1); min-width: 1.5em; justify-content: center; padding-block: 0; padding-inline: var(--s1); pointer-events: none; }
.notification-center-panel { width: min(380px, 92vw); max-width: none; padding: 0; }
.notification-center-head { display: flex; align-items: center; justify-content: space-between; gap: var(--s3); padding: var(--s3) var(--s4); border-block-end: 1px solid var(--rule); }
.notification-center-actions { display: flex; gap: var(--s3); }
.notification-center-list { list-style: none; margin: 0; padding: 0; max-height: 20rem; overflow-y: auto; }
.notification-center-item { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s3); padding: var(--s3) var(--s4); border-block-end: 1px solid var(--rule); font-size: var(--text-sm); }
.notification-center-item:last-child { border-block-end: 0; }
.notification-center-item[data-unread] { border-inline-start: 3px solid var(--accent); }
.notification-center-text { display: flex; flex-direction: column; gap: var(--s1); min-width: 0; }
.notification-center-item[data-unread] .notification-center-title { font-weight: 700; }
.notification-center-desc, .notification-center-time { font-size: var(--text-xs); color: var(--muted); }
.notification-center-empty { margin: 0; padding: var(--s5) var(--s4); text-align: center; font-size: var(--text-sm); color: var(--muted); }

